                      ) : (
                        <>
                          <TableCell className="px-0.5 py-0">
                            <Checkbox
                              label={<span className="sr-only">Play {t.title}</span>}
                              className="flex"
                              checked={!unchecked.has(t.title)}
                              onCheckedChange={(on) =>
                                setUnchecked((u) => {
                                  const next = new Set(u)
                                  if (on) next.delete(t.title)
                                  else next.add(t.title)
                                  return next
