            <FootGlyph name="repeat" />
          </FootButton>
        </div>
        <div className="flex gap-2">
          <FootButton aria-label="Visualiser" on={visuals} onClick={() => setVisuals((v) => !v)}>
            <FootGlyph name="visuals" />
          </FootButton>
          <FootButton
            aria-label="Eject"
            onClick={() => {
              stop()
              onEject()
            }}
          >
            <FootGlyph name="eject" />
          </FootButton>
        </div>
      </div>
    </div>
  )
})

"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { parseColor } from "@/lib/color"

import { ShaderSurface } from "./shader-surface"
import type { Track } from "./ipod-synth"
import type { Tone } from "../tones"

/**
 * The iPod's visualiser: the song in its own colours. A song named for a
 * tone (Bubblegum Gel, Bondi Blue…) plays in that tone's gel, deep to white;
 * one named for a material (Pinstripe, Brushed Metal) in chrome; a station in
 * the desktop's tone. Five scenes — plasma, rings, spectrum bars, a starburst,
 * gel waves — take turns every 16 beats, cross-fading over the last two, in an
 * order the song's seed deals, and everything pulses on the song's beat.
 * Reduced motion, or no WebGL, shows the palette as a still gradient.
 */

const CHROME: Palette = [[27, 31, 38], [138, 146, 158], [213, 218, 226], [255, 255, 255]]

type RGB = [number, number, number]
/** Deep, base, light, highlight. */
type Palette = [RGB, RGB, RGB, RGB]

const mix = (a: RGB, b: RGB, t: number): RGB => [0, 1, 2].map((i) => a[i] + (b[i] - a[i]) * t) as RGB
const WHITE: RGB = [255, 255, 255]
const BLACK: RGB = [0, 0, 0]

/** A tone's gel from its base, deep to white; chrome when there's none. */
function palette(b: RGB | null): Palette {
  if (!b) return CHROME
  return [mix(b, BLACK, 0.7), b, mix(b, WHITE, 0.55), mix(b, WHITE, 0.92)]
}

const f = (n: number) => n.toFixed(3)
const vec3 = (c: RGB) => `vec3(${c.map((v) => f(v / 255)).join(", ")})`

function fragment(p: Palette, bpm: number, seed: number) {
  return `
uniform vec2 u_resolution;
uniform float u_time;

const vec3 C0 = ${vec3(p[0])};
const vec3 C1 = ${vec3(p[1])};
const vec3 C2 = ${vec3(p[2])};
const vec3 C3 = ${vec3(p[3])};
const float BPM = ${f(bpm)};
const float SEED = ${f(seed)};
// Where the song starts in the scenes, and how far it steps each time.
const float FIRST = ${f(seed % 5)};
const float STEP = ${f(1 + (seed % 4))};

vec3 ramp(float x) {
  x = clamp(x, 0.0, 1.0);
  if (x < 0.4) return mix(C0, C1, x / 0.4);
  if (x < 0.8) return mix(C1, C2, (x - 0.4) / 0.4);
  return mix(C2, C3, (x - 0.8) / 0.2);
}

float hash(float n) { return fract(sin(n) * 43758.5453); }

float plasma(vec2 p, float t) {
  float v = sin(p.x * 4.5 + t) + sin(p.y * 6.0 - t * 1.3) + sin((p.x + p.y) * 3.5 + t * 0.7) + sin(length(p * 4.5) - t * 1.6);
  return v * 0.125 + 0.5;
}

float rings(vec2 p, float t, float pulse) {
  float r = length(p);
  return (0.5 + 0.5 * sin(r * 16.0 - t * 4.0 + pulse * 2.0)) * smoothstep(1.3, 0.0, r);
}

/* Sixteen bars, mirrored about the middle, jumping to new heights on each
   beat and swelling with it. */
float bars(vec2 uv, float beat, float pulse) {
  float i = floor(uv.x * 16.0);
  float h = 0.15 + 0.75 * hash(i * 7.1 + beat * 3.3 + SEED) * (0.65 + 0.35 * pulse);
  float y = abs(uv.y - 0.5) * 2.0;
  float lit = step(fract(uv.x * 16.0), 0.78) * step(y, h);
  return lit * (0.45 + 0.55 * (1.0 - y / max(h, 0.001))) + (1.0 - lit) * 0.06;
}

/* The Patina star, breathing on the beat, over turning rays. */
float burst(vec2 p, float t, float pulse) {
  float a = atan(p.y, p.x);
  float r = length(p);
  float rays = (0.5 + 0.5 * cos(a * 10.0 + t * 0.8)) * smoothstep(1.2, 0.1, r) * 0.75;
  float edge = (0.22 + 0.1 * cos(a * 5.0 - t * 0.5)) * (1.0 + 0.3 * pulse);
  return clamp(rays + smoothstep(0.02, 0.0, r - edge), 0.0, 1.0);
}

float waves(vec2 uv, float t) {
  float y = uv.y + 0.08 * sin(uv.x * 6.0 + t * 1.2) + 0.05 * sin(uv.x * 11.0 - t * 0.9);
  return 0.5 + 0.5 * sin(y * 18.0 - t * 2.0);
}

float scene(float m, vec2 uv, vec2 p, float t, float beat, float pulse) {
  if (m < 0.5) return plasma(p, t * 0.8);
  if (m < 1.5) return rings(p, t, pulse);
  if (m < 2.5) return bars(uv, beat, pulse);
  if (m < 3.5) return burst(p, t, pulse);
  return waves(uv, t);
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution;
  vec2 p = (gl_FragCoord.xy - 0.5 * u_resolution) / u_resolution.y;
  float t = u_time;
  float beats = t * BPM / 60.0;
  float beat = floor(beats);
  float pulse = exp(-fract(beats) * 5.0);
  float turn = floor(beats / 16.0);
  float a = scene(mod(FIRST + turn * STEP, 5.0), uv, p, t, beat, pulse);
  float b = scene(mod(FIRST + (turn + 1.0) * STEP, 5.0), uv, p, t, beat, pulse);
  vec3 col = ramp(mix(a, b, smoothstep(14.0, 16.0, mod(beats, 16.0))));
  col *= 0.85 + 0.25 * pulse;
  // The gel's gloss across the top, and a soft falloff to the corners.
  col += 0.12 * smoothstep(0.6, 0.95, uv.y);
  col *= 1.0 - 0.3 * dot(p, p);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
`
}

const css = (c: RGB) => `rgb(${c.map(Math.round).join(", ")})`

export function Visualiser({ track, tone, className }: { track: Track | null; tone: Tone; className?: string }) {
  // A station, or nothing loaded yet, plays in the desktop's tone.
  const own = track && track.bars !== Infinity ? (track.tone ?? null) : tone
  const bpm = track?.bpm ?? 90
  const seed = track?.seed ?? 0
  const box = React.useRef<HTMLDivElement>(null)
  const [shader, setShader] = React.useState<{ fragment: string; p: Palette } | null>(null)

  // The tone's base is read off this box's own data-tone, as y2k.css sets it,
  // so the gel can't drift from the chrome. The shader mounts once it's known
  // (still before the first paint) and recompiles only when the song does.
  React.useLayoutEffect(() => {
    const c = own && box.current ? parseColor(getComputedStyle(box.current).getPropertyValue("--y2k-tone")) : null
    const p = palette(c ? [c.r, c.g, c.b] : null)
    setShader({ fragment: fragment(p, bpm, seed), p })
  }, [own, bpm, seed])

  return (
    <div ref={box} data-tone={own ?? undefined} className={cn("relative", className)}>
      {shader && (
        <ShaderSurface
          fragment={shader.fragment}
          style={{ position: "absolute", inset: 0 }}
          fallback={
            <div
              style={{
                position: "absolute",
                inset: 0,
                backgroundImage: `radial-gradient(circle at 50% 60%, ${css(shader.p[3])} 0%, ${css(shader.p[2])} 22%, ${css(shader.p[1])} 48%, ${css(shader.p[0])} 100%)`,
              }}
            />
          }
        />
      )}
    </div>
  )
}

"use client"

import * as React from "react"

/**
 * A minimal fragment-shader surface: draws a single full-bleed quad and runs
 * the given fragment shader, feeding it `u_resolution` and `u_time`. It handles
 * WebGL context creation, DPR-aware resize, the RAF loop, and cleanup.
 *
 * Graceful degradation: if WebGL is unavailable OR the user prefers reduced
 * motion, nothing is drawn on the canvas and the `fallback` (a CSS layer the
 * caller supplies) shows through instead. Callers should ALWAYS render a
 * `fallback` so the effect has a static, dependency-free substitute.
 */

const VERT = `
attribute vec2 a_pos;
void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }
`

export type ShaderSurfaceProps = React.ComponentProps<"div"> & {
  /** Fragment shader source. Receives uniforms u_resolution (vec2), u_time (float, seconds). */
  fragment: string
  /** CSS fallback shown when WebGL/animation is unavailable. Rendered behind the canvas. */
  fallback: React.ReactNode
}

export function ShaderSurface({ ref, fragment, fallback, style, children, ...props }: ShaderSurfaceProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const [supported, setSupported] = React.useState(false)

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    if (reduce) return // keep fallback

    const gl = canvas.getContext("webgl", { antialias: true, premultipliedAlpha: false })
    if (!gl) return // keep fallback

    // compile
    const compile = (type: number, src: string) => {
      const s = gl.createShader(type)!
      gl.shaderSource(s, src)
      gl.compileShader(s)
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
        console.warn("shader compile error:", gl.getShaderInfoLog(s))
        return null
      }
      return s
    }
    const vs = compile(gl.VERTEX_SHADER, VERT)
    const fs = compile(gl.FRAGMENT_SHADER, `precision highp float;\n${fragment}`)
    if (!vs || !fs) return

    const prog = gl.createProgram()!
    gl.attachShader(prog, vs)
    gl.attachShader(prog, fs)
    gl.linkProgram(prog)
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
      console.warn("shader link error:", gl.getProgramInfoLog(prog))
      return
    }
    gl.useProgram(prog)

    // full-bleed quad
    const buf = gl.createBuffer()
    gl.bindBuffer(gl.ARRAY_BUFFER, buf)
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW)
    const aPos = gl.getAttribLocation(prog, "a_pos")
    gl.enableVertexAttribArray(aPos)
    gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0)

    const uRes = gl.getUniformLocation(prog, "u_resolution")
    const uTime = gl.getUniformLocation(prog, "u_time")

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2)
      const w = canvas.clientWidth * dpr
      const h = canvas.clientHeight * dpr
      if (canvas.width !== w || canvas.height !== h) {
        canvas.width = w
        canvas.height = h
      }
      gl.viewport(0, 0, canvas.width, canvas.height)
      gl.uniform2f(uRes, canvas.width, canvas.height)
    }

    setSupported(true)
    let raf = 0
    // start=0 baseline; use performance.now via the RAF timestamp (no Date.now)
    let start: number | null = null
    const loop = (t: number) => {
      if (start === null) start = t
      resize()
      gl.uniform1f(uTime, (t - start) / 1000)
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)
      raf = requestAnimationFrame(loop)
    }
    raf = requestAnimationFrame(loop)

    const ro = new ResizeObserver(resize)
    ro.observe(canvas)

    return () => {
      cancelAnimationFrame(raf)
      ro.disconnect()
      gl.deleteProgram(prog)
      gl.deleteShader(vs)
      gl.deleteShader(fs)
      gl.deleteBuffer(buf)
    }
  }, [fragment])

  return (
    <div ref={ref} style={{ position: "relative", overflow: "hidden", ...style }} {...props}>
      {/* CSS fallback layer — always present, hidden once WebGL takes over */}
      <div aria-hidden style={{ position: "absolute", inset: 0, opacity: supported ? 0 : 1, transition: "opacity 200ms" }}>
        {fallback}
      </div>
      <canvas ref={canvasRef} aria-hidden style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }} />
      {children != null && <div style={{ position: "relative" }}>{children}</div>}
    </div>
  )
}

/**
 * Colour parsing for token values read back out of the stylesheet.
 *
 * Browsers hand computed custom properties back in whatever form they please —
 * `rgb(232, 68, 154)` as authored, a normalised `#e8449a`, the `#0006` alpha
 * shorthand, or the space-separated `rgb(0 0 0 / 40%)` form — so anything that
 * reads a `--y2k-*` colour has to understand all of them. Parsing this in one
 * place keeps the shaders and the Design System palette from drifting apart
 * when a new syntax shows up.
 */

/** Channels are 0–255; alpha is 0–1. */
export type Rgba = { r: number; g: number; b: number; a: number }

/** Parses a CSS hex or rgb()/rgba() colour. Returns null for anything else
 *  (a gradient, a keyword, an empty custom property) — callers decide what to
 *  fall back to. */
export function parseColor(raw: string): Rgba | null {
  const v = raw.trim()

  const hex = v.match(/^#([0-9a-f]{3,8})$/i)
  if (hex) {
    let h = hex[1]
    if (h.length === 3 || h.length === 4) h = h.split("").map((c) => c + c).join("")
    if (h.length !== 6 && h.length !== 8) return null
    return {
      r: parseInt(h.slice(0, 2), 16),
      g: parseInt(h.slice(2, 4), 16),
      b: parseInt(h.slice(4, 6), 16),
      a: h.length === 8 ? parseInt(h.slice(6, 8), 16) / 255 : 1,
    }
  }

  const fn = v.match(/^rgba?\(([^)]+)\)$/i)
  if (!fn) return null
  const parts = fn[1].split(/[\s,/]+/).filter(Boolean)
  if (parts.length < 3) return null
  // A percentage means 0–100 of the channel's own range: 255 for r/g/b, 1 for α.
  const num = (p: string, full: number) =>
    p.endsWith("%") ? (Number(p.slice(0, -1)) / 100) * full : Number(p)
  const [r, g, b] = parts.slice(0, 3).map((p) => num(p, 255))
  if ([r, g, b].some(Number.isNaN)) return null
  const a = parts.length > 3 ? num(parts[3], 1) : 1
  return { r, g, b, a: Number.isNaN(a) ? 1 : a }
}
